question:
The first relevant chunk is at rank 4 in retrieval. What is its reciprocal rank?

def reciprocal_rank(retrieved, gold):
    for i, cid in enumerate(retrieved, start=1):
        if cid in gold:
            return 1.0 / i
    return 0.0
print(round(reciprocal_rank(["a","b","c","g"], {"g"}), 3))

